CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), phone_number TEXT UNIQUE NOT NULL, email TEXT, notification_prefs JSONB NOT NULL DEFAULT '{"sms":true,"email":true}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS refresh_tokens (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS products (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, category TEXT NOT NULL, quantity NUMERIC NOT NULL CHECK(quantity > 0), unit TEXT NOT NULL, mfg_date DATE, exp_date DATE NOT NULL, image_url TEXT, source TEXT NOT NULL CHECK(source IN ('manual','ocr')), ocr_confidence NUMERIC CHECK(ocr_confidence BETWEEN 0 AND 1), alerts_enabled BOOLEAN NOT NULL DEFAULT true, notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(mfg_date IS NULL OR exp_date > mfg_date));
CREATE INDEX IF NOT EXISTS products_exp_date_idx ON products(exp_date);
CREATE INDEX IF NOT EXISTS products_user_exp_date_idx ON products(user_id, exp_date);
CREATE TABLE IF NOT EXISTS alerts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE, alert_type TEXT NOT NULL CHECK(alert_type IN ('15_day','7_day')), scheduled_for DATE NOT NULL, sent_at TIMESTAMPTZ, channel TEXT NOT NULL CHECK(channel IN ('sms','email')), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sent','failed')), UNIQUE(product_id, alert_type));
CREATE TABLE IF NOT EXISTS notification_log (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), alert_id UUID NOT NULL REFERENCES alerts(id) ON DELETE CASCADE, provider_response JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
